from durationkit import parse_duration
from durationkit.parse import parse_duration as direct_parse
import math

assert parse_duration is direct_parse
valid = {'90': 90.0, '  42 ': 42.0, '0': 0.0, '0007': 7.0, '2d': 172800.0, '3h': 10800.0, '15m': 900.0, '45s': 45.0, '500ms': 0.5, '1h30m': 5400.0, '2d4h': 187200.0, '1m1s': 61.0, '1s500ms': 1.5, '1d1h1m1s1ms': 90061.001, '1d1s': 86401.0, '1h1ms': 3600.001, ' 1h 30m ': 5400.0, '\t1h\n30m\t': 5400.0, '0s': 0.0, '0ms': 0.0, '0d0h0m0s0ms': 0.0, '01h030m': 5400.0, '90m': 5400.0, '1500ms': 1.5}
for value, expected in valid.items():
    result = parse_duration(value)
    assert isinstance(result, float), (value, result)
    assert math.isclose(result, expected, rel_tol=1e-12, abs_tol=1e-12), (value, result, expected)
invalid = ['', '   ', '\t\n', '1 h', '1\tm', '1m s', '-1', '-1h', '+1', '+1h', '1.5', '1.5h', '.5s', '1e3s', '1_000s', '1x', '1H', '1MS', 'h', 'ms', 'abc', '1h1h', '1ms2ms', '0s0s', '30m1h', '1ms1s', '0s0m', '1h30', '1 30m', '1 2', '1h,30m', '1h30m!', '1mss', 'Ⅳ', 'Ⅳh', '½', '½h', '①', '①h', '²', '²s']
for value in invalid:
    try:
        parse_duration(value)
    except ValueError:
        pass
    else:
        raise AssertionError(f'Expected ValueError for {value!r}')
for value in [90, 1.5, None, True, b'90', []]:
    try:
        parse_duration(value)
    except TypeError:
        pass
    else:
        raise AssertionError(f'Expected TypeError for {value!r}')
print(f'Checked {len(valid)} valid, {len(invalid)} invalid, and 6 non-string inputs.')
